// Content models parsed from assets/data/content.json (generated by scripts/generate-content.ts).

List<String> _strings(dynamic v) => (v as List? ?? const []).map((e) => e.toString()).toList();

class SessionItem {
  final String e;
  final int s;
  const SessionItem(this.e, this.s);
  factory SessionItem.fromJson(Map<String, dynamic> j) => SessionItem(j['e'] as String, (j['s'] as num).toInt());
}

List<SessionItem> _items(dynamic v) => (v as List).map((e) => SessionItem.fromJson(e as Map<String, dynamic>)).toList();

class Exercise {
  final String id, name, category, kind, image, level, equipment, description, breath, cue;
  final int durationSec;
  final double kcalPerMin;
  final List<String> focus, steps, benefits;

  /// Optional licensed media (video loop / narrated guidance). Empty until provided.
  final String? video, audio;
  bool get isAffirmation => kind == 'affirmation';
  Exercise.fromJson(Map<String, dynamic> j)
      : id = j['id'],
        name = j['name'],
        category = j['category'],
        kind = j['kind'] ?? 'move',
        video = (j['media'] as Map?)?['video'] as String?,
        audio = (j['media'] as Map?)?['audio'] as String?,
        image = j['image'],
        level = j['level'],
        equipment = j['equipment'],
        description = j['description'],
        breath = j['breath'],
        cue = j['cue'],
        durationSec = (j['durationSec'] as num).toInt(),
        kcalPerMin = (j['kcalPerMin'] as num).toDouble(),
        focus = _strings(j['focus']),
        steps = _strings(j['steps']),
        benefits = _strings(j['benefits']);
}

class Category {
  final String id, name, tagline, description, image;
  final List<String> exerciseIds;
  final int signatureMinutes;
  final List<SessionItem> items;
  final int kcal;
  Category.fromJson(Map<String, dynamic> j)
      : id = j['id'],
        name = j['name'],
        tagline = j['tagline'],
        description = j['description'],
        image = j['image'],
        exerciseIds = _strings(j['exerciseIds']),
        signatureMinutes = (j['signatureMinutes'] as num).toInt(),
        items = _items(j['session']['items']),
        kcal = (j['session']['kcal'] as num).toInt();
}

class QuickSession {
  final String id, title, subtitle, image;
  final List<SessionItem> items;
  final int kcal;
  QuickSession.fromJson(Map<String, dynamic> j)
      : id = j['id'],
        title = j['title'],
        subtitle = j['subtitle'],
        image = j['image'],
        items = _items(j['items']),
        kcal = (j['kcal'] as num).toInt();
}

class PlanDay {
  final int day;
  final String title;
  final bool restore;
  final List<String> focus;
  final List<SessionItem> items;
  final int kcal;
  PlanDay.fromJson(Map<String, dynamic> j)
      : day = (j['day'] as num).toInt(),
        title = j['title'],
        restore = j['restore'] as bool,
        focus = _strings(j['focus']),
        items = _items(j['items']),
        kcal = (j['kcal'] as num).toInt();
}

class Plan {
  final String id, title, subtitle, description, image, group, level, equipment, kind;
  final int minutesPerDay;

  /// Premium programs open only their first [freeDays] days without Enso Plus.
  final bool premium;
  final int freeDays;
  final List<String> benefits;
  final List<PlanDay> days;
  bool get isSingleSession => days.length == 1;
  Plan.fromJson(Map<String, dynamic> j)
      : id = j['id'],
        kind = j['kind'] ?? 'challenge',
        premium = j['premium'] as bool? ?? false,
        freeDays = (j['freeDays'] as num? ?? 0).toInt(),
        title = j['title'],
        subtitle = j['subtitle'],
        description = j['description'],
        image = j['image'],
        group = j['group'],
        level = j['level'],
        equipment = j['equipment'],
        minutesPerDay = (j['minutesPerDay'] as num).toInt(),
        benefits = _strings(j['benefits']),
        days = (j['days'] as List).map((e) => PlanDay.fromJson(e as Map<String, dynamic>)).toList();
}

class ScriptLine {
  final int t;
  final String text;
  ScriptLine.fromJson(Map<String, dynamic> j)
      : t = (j['t'] as num).toInt(),
        text = j['text'];
}

class Meditation {
  final String id, title, subtitle, category, image, track, theme;
  final int minutes;
  final bool premium;
  final List<int>? breath;
  final List<ScriptLine> script;
  Meditation.fromJson(Map<String, dynamic> j)
      : id = j['id'],
        title = j['title'],
        subtitle = j['subtitle'],
        category = j['category'],
        image = j['image'],
        track = j['track'],
        theme = j['theme'],
        minutes = (j['minutes'] as num).toInt(),
        premium = j['premium'] as bool,
        breath = j['breath'] == null ? null : (j['breath'] as List).map((e) => (e as num).toInt()).toList(),
        script = (j['script'] as List).map((e) => ScriptLine.fromJson(e as Map<String, dynamic>)).toList();
}

