  final String id, type, section, title;
  final String? subtitle, minLabel, maxLabel, image, stat;
  final List<OnbOption> options;
  OnbStep.fromJson(Map<String, dynamic> j)
      : id = j['id'],
        type = j['type'],
        section = j['section'],
        title = j['title'],
        subtitle = j['subtitle'],
        minLabel = j['minLabel'],
